import subprocess
import shutil
import gzip
from pathlib import Path

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, Path):
        filepath = Path(filepath)

    if not filepath.exists():
        raise ValueError(f"The file {filepath} does not exist")

    if output_path is None:
        output_path = filepath.with_suffix('.gz')

    if output_path.exists():
        raise ValueError(f"The output file {output_path} already exists")

    try:
        with open(filepath, 'rb') as f_in, gzip.open(output_path, 'wb') as f_out:
            shutil.copyfileobj(f_in, f_out)
        return True
    except Exception as e:
        raise
```

