import subprocess
import os
import shutil

def compress_file(filepath, output_path=None):
    if not filepath or not isinstance(filepath, str):
        raise ValueError("Invalid input: filepath must be a non-empty string")

    if not output_path:
        output_path = f"{os.path.splitext(filepath)[0]}.gz"

    if not shutil.which('gzip'):
        raise RuntimeError("gzip executable not found")

    try:
        subprocess.run(["gzip", "-c", filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        subprocess.run(["mv", f"{filepath}.gz", output_path], check=True)
        return True
    except subprocess.CalledProcessError as e:
        return False
```

