import subprocess

def find_process(process_name):
    try:
        # Use subprocess.run() with list args and capture output
        process_output = subprocess.run(['ps', '-ef'], capture_output=True, text=True, check=True)
        process_output = process_output.stdout
        process_output = process_output.split('\n')
        process_output = [line for line in process_output if process_name in line]
        return '\n'.join(process_output)
    except subprocess.CalledProcessError as e:
        return f"Error running command: {e}"
```

