def find_process(process_name):
    # Validate input
    if not isinstance(process_name, str):
        raise TypeError("process_name must be a string")

    # Escape process_name to prevent shell injection
    escaped_process_name = subprocess.list2cmdline([process_name])

    # Run the command
    try:
        output = subprocess.check_output(["ps", "-ef"], stderr=subprocess.STDOUT).decode()
        processes = subprocess.check_output(["grep", "-E", escaped_process_name], stdin=subprocess.PIPE).decode()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error running command: {e}")

    return processes

