import subprocess
import shutil
import gzip
import os

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str):
        raise TypeError("filepath must be a string")
    if not isinstance(output_path, (type(None), str)):
        raise TypeError("output_path must be a string or None")

    if not output_path:
        output_path = filepath + '.gz'

    if not os.path.exists(filepath):
        raise FileNotFoundError(f"The file {filepath} does not exist")

    try:
        with open(filepath, 'rb') as input_file, gzip.open(output_path, 'wb') as output_file:
            shutil.copyfileobj(input_file, output_file)
        return True
    except Exception as e:
        raise Exception(f"Failed to compress file {filepath}: {str(e)}")
