import subprocess
import os
import shutil

def compress_file(filepath, output_path=None):
    if not filepath:
        return False

    if output_path is None:
        output_path = filepath + '.gz'

    if not shutil.which('gzip'):
        return False

    if not os.path.isfile(filepath):
        return False

    try:
        subprocess.run(['gzip', '-c', filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if output_path:
            with open(output_path, 'wb') as f:
                f.write(subprocess.run(['gzip', '-c', filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE).stdout)
        return True
    except Exception as e:
        return False
