import subprocess
import shutil
import gzip
from pathlib import Path

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str) or not Path(filepath).is_file():
        return False

    if output_path is None:
        output_path = f"{Path(filepath).stem}.gz"
    else:
        if not isinstance(output_path, str):
            return False
        output_path = Path(output_path)

    try:
        with gzip.open(output_path, 'wb') as f_out, open(filepath, 'rb') as f_in:
            shutil.copyfileobj(f_in, f_out)
        return True
    except Exception as e:
        return False
