from pathlib import Path

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, Path):
        raise TypeError("filepath must be a Path object")
    if not filepath.exists():
        logging.error(f"File {filepath} does not exist")
        return False
    if output_path is None:
        output_path = filepath.with_suffix('.gz')
    else:
        output_path = Path(output_path)
        if output_path.exists():
            logging.error(f"Output path {output_path} already exists")
            return False
    command = ['gzip', '-f', '-c', str(filepath), '>', str(output_path)]
    try:
        subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return True
    except subprocess.CalledProcessError as e:
        logging.error(f"Error compressing {filepath}: {e.stderr.decode()}")
        return False
