    if not isinstance(process_name, str):
        raise ValueError("process_name must be a string")

    # Use subprocess to run command with list args for safety
    try:
        output = subprocess.check_output(['ps', '-eo', 'pid,comm', '-C', process_name]).decode('utf-8')
    except subprocess.CalledProcessError as e:
        return f"No running processes found matching {process_name}"

    # Remove header from output
    output = output.split('\n')[2:]

    # Format output as a list of dictionaries
    processes = []
    for line in output:
        pid, name = line.split(maxsplit=1)
        processes.append({"pid": pid, "name": name})

    # Convert list of dictionaries to JSON
    import json
    return json.dumps(processes)

