import subprocess
import shutil
import os

def clone_repo(repo_url, destination):
    if not repo_url or not destination:
        raise ValueError("Both repository URL and destination must be provided")

    destination = os.path.expanduser(destination)
    repo_dir = os.path.join(destination, repo_url.split('/')[-1])

    if not os.path.exists(destination):
        try:
            subprocess.run(['git', 'clone', repo_url, repo_dir], check=True)
            return True
        except subprocess.CalledProcessError:
            return False
    else:
        if not os.path.isdir(repo_dir):
            return False
        try:
            subprocess.run(['git', 'fetch', '--all'], cwd=repo_dir, check=True)
            subprocess.run(['git','reset', '--hard', 'origin/master'], cwd=repo_dir, check=True)
            return True
        except subprocess.CalledProcessError:
            return False
```

