        raise TypeError("process_name must be a string")

    # Use subprocess.run() with list args to avoid using os.system()
    # and to prevent command injection
    try:
        output = subprocess.run(
            ["ps", "-ef"],
            capture_output=True,
            text=True,
            check=True
        ).stdout
    except subprocess.CalledProcessError:
        return ""

    # Use list comprehension and split() to find matching processes
    matching_processes = [
        line.split()
        for line in output.split("\n")
        if process_name in line
    ]

    # Join matching processes into a single string
    return "\n".join([line[-2] for line in matching_processes])
