import os

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str):
        raise TypeError("filepath must be a string")
    if not isinstance(output_path, (str, type(None))):
        raise TypeError("output_path must be a string or None")

    if not filepath:
        raise ValueError("filepath cannot be empty")

    if not os.path.exists(filepath):
        raise FileNotFoundError(f"File {filepath} does not exist")

    if output_path is None:
        output_path = f"{os.path.splitext(filepath)[0]}.gz"

    if output_path == filepath:
        raise ValueError("Output path cannot be the same as the input path")

    try:
        subprocess.run(
            ["gzip", "-c", filepath],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=True,
        )
        with open(output_path, "wb") as f:
            subprocess.run(
                ["gzip", "-dc", filepath],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=True,
            ).stdout
            f.write(subprocess.run(
                ["gzip", "-dc", filepath],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=True,
            ).stdout)
        return True
    except subprocess.CalledProcessError as e:
        return False
