        output_path = Path(output_path)

    if not filepath.exists():
        return False

    if output_path.exists():
        return False

    try:
        with gzip.open(output_path, 'wb') as f_out:
            with open(filepath, 'rb') as f_in:
                shutil.copyfileobj(f_in, f_out)
        return True
    except Exception as e:
        return False
