def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str) or not isinstance(output_path, (str, type(None))):
        raise TypeError("Both filepath and output_path must be strings or None")

    if not filepath or not output_path:
        raise ValueError("Both filepath and output_path must be non-empty")

    if not os.path.exists(filepath):
        raise FileNotFoundError(f"The file {filepath} does not exist")

