        "--sort", "rss",
        "--no-headers",
        "|", "grep", process_name_escaped
    ]

    try:
        output = subprocess.check_output(command)
        return output.decode("utf-8").strip()
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to run command: {e}")
