import subprocess
import shutil

def get_disk_usage(directory):
    try:
        # Validate input to prevent directory traversal and ensure it exists
        if not isinstance(directory, str) or not directory:
            raise ValueError("Invalid directory")
        if not os.path.isdir(directory):
            raise ValueError("Directory does not exist")

        # Use subprocess.run with list args for safer execution
        du_output = subprocess.run(['du', '-sh', directory], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Check for errors
        if du_output.returncode!= 0:
            raise subprocess.CalledProcessError(du_output.returncode, du_output.stderr.decode())

        # Decode and strip output
        return du_output.stdout.decode().strip()

    except subprocess.CalledProcessError as e:
        # Raise a custom error with more context
        raise DiskUsageError(f"Failed to get disk usage: {e.stderr.decode()}")

    except Exception as e:
        # Catch and re-raise unexpected errors
        raise RuntimeError(f"Unexpected error: {e}")
```

