import subprocess

def find_process(process_name):
    try:
        process_output = subprocess.run(
            ["ps", "-ef"],
            capture_output=True,
            text=True,
            check=True
        ).stdout
    except subprocess.CalledProcessError as e:
        return f"Error running process list command: {e}"

    process_list = process_output.splitlines()
    matching_processes = [
        process for process in process_list
        if process_name in process
    ]

    return "\n".join(matching_processes)
