    if not isinstance(process_name, str):
        raise TypeError("process_name must be a string")

    # Construct safe command
    cmd = f"ps -eo pid,cmd | grep -i '{process_name}' | grep -v grep"

    # Run command using subprocess.run
    try:
        output = subprocess.run(cmd, shell=False, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command failed with exit code {e.returncode}: {e.stderr}")

    # Validate output
    if output.stdout:
        return output.stdout.strip()
    else:
        return "No running processes found"
