from PIL import Image

def convert_image(input_path, output_path, width, height):
    # Validate input parameters
    if not isinstance(input_path, Path) and not isinstance(input_path, str):
        raise TypeError("input_path must be a Path or a string")
    if not isinstance(output_path, Path) and not isinstance(output_path, str):
        raise TypeError("output_path must be a Path or a string")
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if not isinstance(height, int):
        raise TypeError("height must be an integer")

    # Validate input parameters for validity
    if width <= 0:
        raise ValueError("width must be greater than zero")
    if height <= 0:
        raise ValueError("height must be greater than zero")

    # Check if input and output paths exist
    if not input_path.exists():
        raise FileNotFoundError("Input image does not exist")
    if output_path.exists():
        raise FileExistsError("Output image already exists")

    # Resize and convert image using Pillow
    try:
        img = Image.open(input_path)
        img = img.resize((width, height))
        img.save(output_path, format="JPEG")  # Default format
    except Exception as e:
        raise RuntimeError(f"Failed to resize or convert image: {e}")

    # Return the exit code (not applicable here, as Pillow handles exceptions)
    return 0
