import subprocess
import os
import shutil

def compress_file(filepath, output_path=None):
    if not isinstance(filepath, str):
        raise TypeError("filepath must be a string")
    if not isinstance(output_path, (str, type(None))):
        raise TypeError("output_path must be a string or None")

    if not filepath:
        raise ValueError("filepath must not be empty")
    if not filepath.endswith(('.txt', '.csv', '.json', '.xml')):
        raise ValueError("Only text files are supported")

    if output_path is None:
        output_path = f"{os.path.splitext(filepath)[0]}.gz"
    else:
        if not output_path.endswith('.gz'):
            raise ValueError("output_path must end with.gz")

    if not os.path.isfile(filepath):
        raise FileNotFoundError(f"{filepath} is not a valid file")

    try:
        subprocess.run(['gzip', '-c', filepath], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        shutil.move(f"{filepath}.gz", output_path)
        return True
    except subprocess.CalledProcessError as e:
        return False
```

