import subprocess
import re

def convert_image(input_path, output_path, width, height):
    if not isinstance(input_path, str) or not isinstance(output_path, str):
        raise TypeError("Input and output paths must be strings")

    if not isinstance(width, int) or not isinstance(height, int):
        raise TypeError("Width and height must be integers")

    if width <= 0 or height <= 0:
        raise ValueError("Width and height must be positive")

    # Validate input path
    if not re.match(r'^.+\.jpg$|\.jpeg$|\.png$|\.gif$|\.bmp$', input_path, re.IGNORECASE):
        raise ValueError("Invalid input image format")

    # Validate output path
    if not re.match(r'^.+\.jpg$|\.jpeg$|\.png$|\.gif$|\.bmp$', output_path, re.IGNORECASE):
        raise ValueError("Invalid output image format")

    command = f"convert -resize {width}x{height} {input_path} {output_path}"
    try:
        return subprocess.call(command, shell=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to convert image: {e}")
